import functools


def collect_errors(validators, data):
    errors = []
    for validator in validators:
        try:
            validator(data)
        except Exception as e:
            errors.append(e)
    return errors


def retry_on(exception_types, max_retries=3):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(max_retries):
                try:
                    return fn(*args, **kwargs)
                except exception_types as e:
                    last_error = e
            raise last_error
        return wrapper
    return decorator


def null_safe(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        try:
            return fn(*args, **kwargs)
        except (AttributeError, TypeError):
            return None
    return wrapper
